using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

/// <summary>
/// Shared fixture that boots the Aspire AppHost and exposes the chat client
/// for evaluation scenarios.
/// </summary>
public sealed class EvaluationFixture : IAsyncLifetime
{
    private DistributedApplication? _app;

    public IChatClient ChatClient { get; private set; } = null!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        var chatResource = _app.GetConnectionString("chat");

        // Resolve the chat client from the app's service provider.
        ChatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation tests that measure response quality of the chat agent.
/// </summary>
public sealed class ChatEvaluationTests : IClassFixture<EvaluationFixture>
{
    private readonly EvaluationFixture _fixture;

    public ChatEvaluationTests(EvaluationFixture fixture)
    {
        _fixture = fixture;
    }

    [Theory]
    [MemberData(nameof(Scenarios))]
    public async Task EvaluateScenario(string scenarioName, string userMessage, string context)
    {
        // Send message to the chat agent.
        var response = await _fixture.ChatClient.GetResponseAsync(userMessage);
        var responseText = response.Text ?? string.Empty;

        // Build the evaluation turn.
        var chatTurn = new ChatTurn(userMessage, responseText, context);

        // Run quality evaluators.
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var results = new EvaluationResults();
        foreach (var evaluator in evaluators)
        {
            var metrics = await evaluator.EvaluateAsync(
                [chatTurn],
                _fixture.ChatClient);

            foreach (var metric in metrics)
            {
                results.Metrics.Add(metric);
            }
        }

        // Assert minimum quality thresholds.
        foreach (var metric in results.Metrics)
        {
            if (metric is NumericMetric numeric)
            {
                Assert.True(
                    numeric.Value >= 3.0,
                    $"Scenario '{scenarioName}': {metric.Name} scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    public static TheoryData<string, string, string> Scenarios => new()
    {
        {
            "greeting",
            "Hello, how can you help me today?",
            "The assistant should respond politely and describe its capabilities."
        },
        {
            "factual-question",
            "What is the capital of France?",
            "The capital of France is Paris."
        },
    };
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evaluation;

/// <summary>
/// Runs evaluation scenarios and persists results to a local report for review.
/// </summary>
public sealed class ReportingTests : IClassFixture<EvaluationFixture>
{
    private static readonly string ReportPath =
        Path.Combine(AppContext.BaseDirectory, "evaluation-report");

    private readonly EvaluationFixture _fixture;

    public ReportingTests(EvaluationFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task GenerateEvaluationReport()
    {
        var storage = new DiskBasedReportingStorage(ReportPath);
        var scenarios = GetScenarios();

        foreach (var (name, userMessage, context) in scenarios)
        {
            var response = await _fixture.ChatClient.GetResponseAsync(userMessage);
            var responseText = response.Text ?? string.Empty;

            var chatTurn = new ChatTurn(userMessage, responseText, context);

            var evaluators = new IEvaluator[]
            {
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            };

            var results = new EvaluationResults();
            foreach (var evaluator in evaluators)
            {
                var metrics = await evaluator.EvaluateAsync(
                    [chatTurn],
                    _fixture.ChatClient);

                foreach (var metric in metrics)
                {
                    results.Metrics.Add(metric);
                }
            }

            await storage.StoreResultsAsync(name, results);
        }
    }

    private static IEnumerable<(string Name, string UserMessage, string Context)> GetScenarios()
    {
        yield return ("greeting", "Hello, how can you help me today?",
            "The assistant should respond politely and describe its capabilities.");
        yield return ("factual-question", "What is the capital of France?",
            "The capital of France is Paris.");
        yield return ("summarization", "Summarize the benefits of cloud computing in two sentences.",
            "Cloud computing offers scalability, cost savings, and global accessibility.");
    }
}

