using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evaluation;

/// <summary>
/// Runs evaluation scenarios and persists results to a local report for review.
/// </summary>
public sealed class ReportingTests : IClassFixture<EvaluationFixture>
{
    private static readonly string ReportPath =
        Path.Combine(AppContext.BaseDirectory, "evaluation-report");

    private readonly EvaluationFixture _fixture;

    public ReportingTests(EvaluationFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task GenerateEvaluationReport()
    {
        var resultStore = new DiskBasedResultStore(ReportPath);
        var chatConfig = new ChatConfiguration(_fixture.ChatClient);

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var reportingConfig = new ReportingConfiguration(
            evaluators,
            resultStore,
            chatConfig);

        foreach (var (name, userMessage, context) in GetScenarios())
        {
            await using var scenarioRun = await reportingConfig.CreateScenarioRunAsync(name);

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, userMessage)
            };

            var response = await _fixture.ChatClient.GetResponseAsync(messages);

            var contexts = new EvaluationContext[]
            {
                new GroundednessEvaluatorContext(context)
            };

            var result = await scenarioRun.EvaluateAsync(messages, response, contexts);

            // Verify all numeric metrics meet minimum threshold.
            foreach (var metric in result.Metrics.Values)
            {
                if (metric is NumericMetric numeric)
                {
                    Assert.True(
                        numeric.Value >= 3.0,
                        $"Scenario '{name}': {metric.Name} scored {numeric.Value}, expected >= 3.0");
                }
            }
        }
    }

    private static IEnumerable<(string Name, string UserMessage, string Context)> GetScenarios()
    {
        yield return ("greeting", "Hello, how can you help me today?",
            "The assistant should respond politely and describe its capabilities.");
        yield return ("factual-question", "What is the capital of France?",
            "The capital of France is Paris.");
        yield return ("summarization", "Summarize the benefits of cloud computing in two sentences.",
            "Cloud computing offers scalability, cost savings, and global accessibility.");
    }
}

