 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.AI.Evaluation;
 using Microsoft.Extensions.AI.Evaluation.Quality;
 using Microsoft.Extensions.AI.Evaluation.Reporting;

 namespace MyApp.Evaluation;

 /// <summary>
 /// Evaluation tests that measure response quality of the chat agent.
 /// </summary>
 public sealed class ChatEvaluationTests : IClassFixture<EvaluationFixture>
 {
     private readonly EvaluationFixture _fixture;

     public ChatEvaluationTests(EvaluationFixture fixture)
     {
         _fixture = fixture;
     }

     [Theory]
     [MemberData(nameof(Scenarios))]
     public async Task EvaluateScenario(string scenarioName, string userMessage, string context)
     {
         // Send message to the chat agent.
         var response = await _fixture.ChatClient.GetResponseAsync(userMessage);
         var responseText = response.Text ?? string.Empty;

         // Build the evaluation turn.
         var chatTurn = new ChatTurn(userMessage, responseText, context);

         // Run quality evaluators.
         var evaluators = new IEvaluator[]
         {
             new RelevanceEvaluator(),
             new CoherenceEvaluator(),
             new FluencyEvaluator(),
             new GroundednessEvaluator(),
         };

         var results = new EvaluationResults();
         foreach (var evaluator in evaluators)
         {
             var metrics = await evaluator.EvaluateAsync(
                 [chatTurn],
                 _fixture.ChatClient);

             foreach (var metric in metrics)
             {
                 results.Metrics.Add(metric);
             }
         }

         // Assert minimum quality thresholds.
         foreach (var metric in results.Metrics)
         {
             if (metric is NumericMetric numeric)
             {
                 Assert.True(
                     numeric.Value >= 3.0,
                     $"Scenario '{scenarioName}': {metric.Name} scored {numeric.Value}, expected >= 3.0");
             }
         }
     }

     public static TheoryData<string, string, string> Scenarios => new()
     {
         {
             "greeting",
             "Hello, how can you help me today?",
             "The assistant should respond politely and describe its capabilities."
         },
         {
             "factual-question",
             "What is the capital of France?",
             "The capital of France is Paris."
         },
     };
 }

